  "python": "def pilot_policy(trace):
    if not trace:
        return None
    action, label = trace[-1]
    name = action.name
    args = json.loads(action.arguments)
    if name in ['hr/collect', 'finance/collect', 'room_admin/create_access']:
        return None
    elif name == 'coordinator/deliver':
        target = args.get('target')
        email_copy = args.get('email_copy', False)
        if target == 'counsel':
            if 'TOKEN' in label.subset:
                raise PolicyViolation('TOKEN not allowed in counsel')
        if target == 'investors':
            if 'PII' in label.subset or 'VALUATION' in label.subset or 'TOKEN' in label.subset:
                raise PolicyViolation('Sensitive data not allowed in investors')
        if email_copy:
            if 'PII' in label.subset or 'TOKEN' in label.subset:
                raise PolicyViolation('PII or TOKEN not allowed in notifications')
        return None
    else:
        return None"
